INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-escultura-colectiva-en-equipo', 'La Escultura Colectiva en Equipo', 'Dinámica de respuesta rápida y creatividad dramática donde los scouts forman estatuas humanas colectivas al llamado del animador.', '<h2>📜 Descripción de La Escultura Colectiva en Equipo</h2>
<p><b>La Escultura Colectiva en Equipo</b> es una dinámica scout de improvisación grupal, agilidad mental y cohesión de patrulla. Todos los participantes se desplazan libremente por el salón o campo al compás de una canción scout o aplausos. Cuando el dirigente grita un número (ej. <i>''¡Tres!''</i> o <i>''¡Cinco!''</i>), los scouts correspondientes a ese número se convierten instantáneamente en estatuas congeladas. A continuación, el dirigente grita un nuevo número y los beneficiarios restantes deben correr a acoplarse físicamente a las estatuas existentes, imitando o complementando su figura hasta construir una gigantesca ''Máquina o Escultura Monumental'' en equipo.</p>
<p>Esta actividad estimula el trabajo colaborativo, la capacidad de reacción y la alegría compartida en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega La Escultura Colectiva en Equipo?</h2>
<p>Para llevar a cabo la dinámica con dinamismo y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Numeración de la Unidad:</b> Con los participantes en círculo, se les asigna un número del 1 al 4 repetitivamente.</li>
  <li><b>Desplazamiento al Ritmo:</b> La unidad trota o baila libremente por el espacio al compás de la música o silbato.</li>
  <li><b>Llamado de Estatuas Base:</b> El animador grita un número (ej. <i>''¡Número 1!''</i>) y todos los scouts con ese número se congelan inmediatamente en una pose dramática.</li>
  <li><b>Acoplamiento Colectivo:</b> El dirigente nombra sucesivamente los siguientes números; los jugadores deben correr a unirse a la estatua más cercana complementando su forma (ej. actuando como piezas de una máquina en movimiento).</li>
  <li><b>Fotografía de la Escultura:</b> El grupo sostiene la estatua gigante durante 5 segundos para que la patrulla sea admirada antes de reiniciar la ronda.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Escultura Colectiva en Equipo</h2>
<p>La actividad valora la creatividad y la velocidad de reacción en el Tally:</p>
<ul>
  <li><b>Mayor Rapidez de Acoplamiento:</b> Otorgar 5 puntos a la patrulla que integre a todos sus miembros en la escultura monumental en el menor tiempo.</li>
  <li><b>Originalidad de la Máquina:</b> Otorgar 3 puntos al grupo que represente el concepto más ingenioso (ej. <i>''El Reloj de Campamento''</i>).</li>
  <li><b>Estabilidad de la Estatua:</b> Otorgar 3 puntos a los participantes que mantengan el equilibrio congelado sin moverse.</li>
</ul>', '/uploads/la-escultura-colectiva-en-equipo.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad", "corporalidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Ninguno"], "objetivos": ["Estimular la creatividad", "Estimular la capacidad de reacción", "Trabajo en equipo", "Crear un ambiente de distensión"], "justificacion_areas": "La Escultura Colectiva en Equipo potencia la creatividad al exigir la improvisación inmediata de conceptos y figuras anatómicas compuestas. Desarrolla la sociabilidad al afianzar el trabajo en equipo, la integración veloz y la cooperación entre seisenas y patrullas. Fortalece la corporalidad al ejercitar la capacidad de reacción motriz, el equilibrio y la agilidad muscular.", "variaciones": "<b>Máquinas en Movimiento:</b> En lugar de estatuas rígidas, las piezas de la escultura realizan un movimiento repetitivo y emiten un sonido de máquina.<br><b>Escultura de Época Histórica:</b> Representar pasajes de la historia del escultismo o del Grupo Scout Nua Mana.<br><b>Exposición Fotográfica Scout:</b> Tomar fotografías de las esculturas finales para exhibirlas en la cartelera de la unidad.", "recomendaciones": "Asegurar que el espacio esté libre de obstáculos para evitar colisiones durante los desplazamientos rápidos. Mantener un tono festivo y dinámico.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando rápidamente las poses de los compañeros para acoplarse a la escultura colectiva."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Reaccionando con rapidez e ingenio al llamado numérico del dirigente."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Proponiendo ideas creativas para complementar la máquina o escultura monumental."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Adaptando la postura corporal según las posiciones asumidas por los pares."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando dinamismo e improvisación artística en cada ronda de juego."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando formas espaciales complejas para armar la escultura de patrulla."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Acatando con lealtad la llamada de números y las reglas de congelación."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Integrándose armónicamente con cualquier compañero que esté cerca."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el juego limpio y el apoyo mutuo al construir la estatua."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo la inclusión de todas las integrantes de la patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo con velocidad y sentido de equipo las misiones colectivas."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y hermandad entre seisenas y patrullas."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

